// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }
    function testFuzz_property(address logAddr) public {
        vm.assume(logAddr != address(0));
        bool ok;
        try c.SetLogFile(logAddr) { ok = true; } catch { ok = false; }
        // General rule: on a freshly deployed (uninitialized) contract, SetLogFile
        // must succeed for every admissible address. The mutant's inverted lock
        // reverts every nonReentrant_-guarded call, including SetLogFile.
        assertTrue(ok);
    }
}
